def _canonical_set_ok(arr) -> bool:
    if type(arr) is not list:
        return False
    keys = [C.canonical(v) for v in arr]
    return keys == sorted(keys) and len(keys) == len(set(keys))


def _obj(objects: dict, domain: str, digest: str):
